/* Load after MW_PayoutDashboard.js. Uses the existing dashboard; no extra login or PIN. */
let prFeed=null,prOffset=0,prBusy=false,prProfile=null,prAction=null,prPreview=null,prProfileSequence=0,prFundSequence=0;
const PR_HTML=`<section class="card fp-panel" id="sec-payment-review"><div class="card-header"><span class="card-title">Contribution payments</span></div><div class="fp-body">
<p>Review recent contributions, resolve payment issues and open member payment histories.</p>
<div id="pr-counts"></div>
<div class="fp-fields"><div><label for="pr-query">Member ID, name, sender or memo</label><input id="pr-query" placeholder="Search payments" onkeydown="if(event.key==='Enter')prLoad(0)"></div><div><label for="pr-filter">Show</label><select id="pr-filter" onchange="prLoad(0)"><option value="ALL">All non-registration payments</option><option value="REVIEW">Needs review</option><option value="DISMISSED">Dismissed history</option></select></div></div>
<div class="fp-actions"><button class="hero-btn secondary" type="button" onclick="prShowZelleReview()">Zelle review</button><button class="hero-btn primary" onclick="prLoad(0)">Refresh payments</button><button class="hero-btn secondary" id="pr-prev" onclick="prLoad(Math.max(0,prOffset-50))">Previous page</button><button class="hero-btn secondary" id="pr-next" onclick="prLoad(prOffset+50)">Next page</button></div>
<div id="pr-message" role="status" aria-live="polite"></div><div id="pr-pending"></div><div id="pr-payments"></div>
<details style="margin-top:24px"><summary>Payment dates &amp; outstanding by fund</summary><label for="pr-fund">Fundraiser</label><select id="pr-fund" onchange="prLoadFund()"><option value="">Select a fund</option></select><div class="fp-actions"><button class="hero-btn secondary" onclick="prLoadFund()">Refresh fund list</button></div><div id="pr-fund-list"></div></details>
</div></section>`;
function prMessage(text,error){const e=document.getElementById('pr-message');if(e){e.textContent=text;e.className=error?'fp-error':'';}}
function prInvalidate(){prPreview=null;const b=document.getElementById('pr-apply');if(b)b.disabled=true;const e=document.getElementById('pr-action-preview');if(e)e.textContent='';}
function prTable(headers,rows){return '<div class="fp-table-wrap"><table><thead><tr>'+headers.map(h=>'<th>'+fpEscape(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';}
function prProfileButton(id,label){return id?'<button class="hero-btn secondary mw-member-link" title="Open member profile" onclick="openDrawer(\''+id+'\',\'\')">'+fpEscape(label||id)+'</button>':'Unassigned';}
async function prLoad(offset=0){
 if(prBusy)return;prBusy=true;ftBusy=true;prMessage('Reading PAYMENTS…');
 try{prFeed=await fpCall('fp_review_feed',{offset,query:document.getElementById('pr-query').value,reviewOnly:document.getElementById('pr-filter').value==='REVIEW'?'YES':'NO',statusFilter:document.getElementById('pr-filter').value==='DISMISSED'?'DISMISSED':''});prOffset=prFeed.offset;
  document.getElementById('pr-counts').innerHTML='<div class="mw-review-stats"><div class="mw-review-stat"><span>Matching payments</span><strong>'+Number(prFeed.total).toLocaleString()+'</strong></div><div class="mw-review-stat mw-review-attention"><span>Need review · all records</span><strong>'+Number(prFeed.stats.review).toLocaleString()+'</strong></div><div class="mw-review-stat mw-review-confirmed"><span>Recorded contributions</span><strong>'+fpMoney(prFeed.stats.confirmedCash)+'</strong></div></div>';
  document.getElementById('pr-prev').disabled=prOffset===0;document.getElementById('pr-next').disabled=prOffset+50>=prFeed.total;
  document.getElementById('pr-payments').innerHTML=prTable(['Payment date','Member / sender','Amount','Type / fund','Status / issues','Email','Action'],prFeed.payments.map(r=>[
   fpEscape(r.date||'Date needs review'),prProfileButton(r.memberId,r.name||r.memberId)+'<div>'+fpEscape(r.sender)+'</div>',fpMoney(r.amount),fpEscape(r.type)+'<br>'+fpEscape(r.fund||'No fund')+'<br><small>PAYMENTS row '+r.row+'</small>','<span class="mw-payment-status '+(r.needsReview?'needs-review':'')+'">'+fpEscape(r.status)+'</span><br>'+r.reasons.map(fpEscape).join('<br>'),'<strong>'+fpEscape(r.emailState||'NOT RECORDED')+'</strong><br><small>'+fpEscape(r.emailStatus||'No delivery status recorded')+'</small>','<button class="hero-btn secondary" onclick="prOpenPayment('+r.row+')">'+(r.canAllocate?'Fix / allocate':'Inspect')+'</button>'
  ]));
  ['sec-members','sec-activity'].forEach(id=>{const e=document.getElementById(id);if(e)e.style.display='none';});
  document.querySelectorAll('#main-content .card-title').forEach(e=>{if(['Priority pulse','Eligibility status'].includes(e.textContent.trim()))e.closest('.card').style.display='none';});
  document.getElementById('pr-pending').innerHTML=prFeed.pendingAction?'<div class="fp-note">Unfinished approved action: '+fpEscape(prFeed.pendingAction)+' <button class="hero-btn secondary" onclick="prResume()">Resume approved action</button></div>':'';
  const list=await fpCall('fp_funds'),select=document.getElementById('pr-fund'),cur=select.value;select.replaceChildren(new Option('Select a fund',''));list.funds.forEach(f=>select.add(new Option(f.code+' — '+f.deceased+' ('+f.status+')',f.code)));select.value=cur;
  prMessage('Newest payments first. Open a member name for payment history.');
 }catch(e){prMessage(e.message,true);}finally{prBusy=false;ftBusy=false;}
}
async function prLoadFund(){const code=document.getElementById('pr-fund').value;if(!code){document.getElementById('pr-fund-list').textContent='Select a fund.';return;}await mwFundRoster(code,'pr-fund-list');}
openDrawer=async function(memberId,memberName){
 const seq=++prProfileSequence;drawerOpen=true;document.body.style.overflow='hidden';document.getElementById('drawer-backdrop').classList.add('open');document.getElementById('member-drawer').classList.add('open');document.getElementById('drawer-name').textContent=memberName||memberId;document.getElementById('drawer-id').textContent=memberId;document.getElementById('drawer-body').textContent='Reading exact member and fund records…';
 try{const d=await fpCall('fp_review_profile',{memberId});if(seq!==prProfileSequence||!drawerOpen)return;prProfile=d;prRenderProfile();}catch(e){if(seq===prProfileSequence)document.getElementById('drawer-body').textContent=e.message;}
};
let prProfileTab='details';
function prSelectProfileTab(tab){
 prProfileTab=tab;['details','obligations','payments','beneficiaries','claims'].forEach(name=>{const el=document.getElementById('pr-profile-'+name),button=document.getElementById('pr-profile-tab-'+name);if(el)el.hidden=name!==tab;if(button){button.setAttribute('aria-selected',String(name===tab));}});
}
function prRenderProfile(){
 const d=prProfile;if(!d)return;mwStatementPreview=null;prAction=null;prPreview=null;prProfileTab='details';
 document.getElementById('drawer-name').textContent=d.name;document.getElementById('drawer-id').textContent=d.memberId+' · Joined '+d.joined;
 const tabs=[['details','Profile details'],['obligations','Fund obligations'],['payments','Payments'],['beneficiaries','Beneficiaries'],['claims','Claimed funds']];
 const obligations=d.obligations.slice().sort((a,b)=>b.fundCode.localeCompare(a.fundCode));
 const fields=[['Email',d.email],['Phone',d.phone],['Emergency contact / phone',d.emergencyContact],['Location',d.location],['Date joined',d.joined],['Registration confirmed',d.adminStatus?.registrationConfirmedAt||'Not verified']];
 const credit='<div class="mw-credit-box"><span>Available funeral credit</span><strong>'+fpMoney(d.availableCredit)+'</strong><p>Choose a fund under Fund obligations to apply available credit.</p></div>';
 const obligationsHtml=prTable(['Fund / deadline','Status','Paid / credit applied','Outstanding','Dates paid','Action'],obligations.map(o=>[fpEscape(o.fundCode)+'<br>'+fpEscape(o.deceased)+'<br>'+fpEscape(o.deadline),fpEscape(o.status),fpMoney(o.paid)+' / '+fpMoney(o.creditApplied),o.balance===null?'Review':fpMoney(o.balance)+(o.lateFeePending?'<br><small>Includes $5 late fee awaiting assessment</small>':''),(o.paymentDates||[]).map(fpEscape).join('<br>')||'No recorded payment',d.availableCredit>0&&o.balance>0&&o.status!=='REVIEW'&&o.status!=='EXEMPT'?'<button class="hero-btn secondary" onclick="prStartCredit(\''+o.fundCode+'\')">Apply credit</button>':'']));
 document.getElementById('drawer-body').innerHTML='<div class="mw-profile-nav" role="tablist" aria-label="Member profile">'+tabs.map(([id,label])=>'<button type="button" role="tab" id="pr-profile-tab-'+id+'" aria-controls="pr-profile-'+id+'" onclick="prSelectProfileTab(\''+id+'\')">'+label+'</button>').join('')+'</div><div class="fp-body">'+
 '<section id="pr-profile-details" role="tabpanel"><div class="fp-actions"><button class="hero-btn primary" onclick="mwStartStatement()">Send balance &amp; owing history</button></div><div id="mw-statement"></div>'+mwProfileStanding(d)+'<div class="mw-profile-fields">'+fields.map(([l,v])=>'<div><span>'+fpEscape(l)+'</span><strong>'+fpEscape(v||'Not recorded')+'</strong></div>').join('')+'</div>'+credit+'<div class="fp-note">'+fpEscape(d.adminStatus?.note||'Verify registration, declaration timing and overdue arrears before approving benefits.')+'</div><h3>Issues to review ('+d.issues.length+')</h3><ul>'+d.issues.map(x=>'<li>'+fpEscape(x)+'</li>').join('')+'</ul></section>'+
 '<section id="pr-profile-obligations" role="tabpanel" hidden>'+credit+obligationsHtml+'</section><section id="pr-profile-payments" role="tabpanel" hidden><h3>Payment history · newest first</h3>'+prTable(['Date','Fund / type','Amount','Status','Email','Memo / source'],d.payments.map(p=>[fpEscape(p.date),fpEscape(p.fund)+'<br>'+fpEscape(p.type),fpMoney(p.amount),fpEscape(p.status),fpEscape(p.emailState||'NOT RECORDED')+'<br>'+fpEscape(p.emailStatus||''),fpEscape(p.memo)+'<br>PAYMENTS row '+p.row]))+'</section>'+
 '<section id="pr-profile-beneficiaries" role="tabpanel" hidden><h3>Beneficiaries</h3>'+prBeneficiaryCards(d)+'</section><section id="pr-profile-claims" role="tabpanel" hidden><h3>Previously claimed funeral funds</h3><p>Dates show when each fund was opened.</p>'+prClaimHistory(d.claimedFunds||[])+(d.claimWarnings||[]).map(w=>'<div class="fp-note">'+fpEscape(w)+'</div>').join('')+'</section><div id="pr-action"></div></div>';
 prSelectProfileTab('details');
}
function prClaimHistory(claims){return claims.length?prTable(['Deceased','Relationship','Fund number','Fund opened','Claim record'],claims.map(c=>[fpEscape(c.deceased||'Not recorded'),fpEscape(c.relationship||'Not recorded'),fpEscape(c.fundCode),fpEscape(c.fundOpenedDate||'Date not recorded'),fpEscape(c.recordedClaim?'Not qualified — previously claimed':c.fundStatus+' — verify claim status')])):'<p>No claimed fund is linked to this member ID.</p>';}
function prBeneficiaryCards(d){
 const records=d.beneficiaries||[];
 if(!records.length)return '<p>'+fpEscape((d.claimWarnings||[]).length?'Claim history could not be verified. See Claimed funds for details.':'No beneficiaries recorded.')+'</p>';
 return '<p>'+fpEscape(d.claimPolicyNote||'')+'</p>'+records.map(b=>'<article class="mw-beneficiary '+(b.status==='PREVIOUSLY_CLAIMED'?'mw-beneficiary-claimed':b.status==='REVIEW'?'mw-beneficiary-review':'')+'"><div class="mw-beneficiary-heading"><div><span>'+fpEscape(b.relationship.charAt(0).toUpperCase()+b.relationship.slice(1))+'</span><h4>'+fpEscape(b.name)+'</h4></div><strong class="mw-beneficiary-label">'+fpEscape(b.label)+'</strong></div>'+(b.claims||[]).map(c=>'<p><strong>'+fpEscape(c.fundCode)+'</strong> · Fund opened '+fpEscape(c.fundOpenedDate||'date not recorded')+' · '+fpEscape(c.deceased)+'</p>').join('')+(b.possibleClaims||[]).map(c=>'<p>Check '+fpEscape(c.fundCode)+' · '+fpEscape(c.deceased)+' · '+fpEscape(c.memberId||'member not recorded')+' · Fund opened '+fpEscape(c.fundOpenedDate||'date not recorded')+'. Names alone do not establish the same person.</p>').join('')+'</article>').join('');
}
function prShowZelleReview(){document.getElementById('pr-filter').value='REVIEW';prLoad(0);document.getElementById('mw-bank-emails')?.setAttribute('open','');}
function prStartDismiss(){if(!prAction||prAction.mode!=='ALLOCATE')return;const row=prAction.sourceRow;prAction={mode:'DISMISS',sourceRow:row,requestId:crypto.randomUUID()};prPreview=null;prActionShell('Dismiss unresolved payment','<p>This marks the original payment DISMISSED and keeps its sender, amount, date and memo. It does not reverse a confirmed payment or change fund balances.</p><label for="pr-dismiss-reason">Reason</label><input id="pr-dismiss-reason" maxlength="500" minlength="5" required oninput="prInvalidate()" placeholder="Explain why this payment should be dismissed">');}
function prActionShell(title,body){document.getElementById('pr-action').innerHTML='<h3 style="margin:20px 0">'+fpEscape(title)+'</h3>'+body+'<div class="fp-actions"><button class="hero-btn secondary" onclick="prPreviewAction()">Dry run / preview</button><button id="pr-apply" class="hero-btn primary" disabled onclick="prApplyAction()">Confirm and apply</button><button class="hero-btn secondary" onclick="prCancelAction()">Cancel</button></div><div id="pr-action-preview" role="status" style="white-space:pre-wrap"></div>';document.getElementById('pr-action').scrollIntoView({block:'nearest'});}
function prStartCredit(code){
 const o=prProfile.obligations.find(o=>o.fundCode===code);prAction={mode:'CREDIT',requestId:crypto.randomUUID(),memberId:prProfile.memberId,fundCode:code};prPreview=null;
 prActionShell('Apply available credit to '+code,'<p>Available: '+fpMoney(prProfile.availableCredit)+'; this fund outstanding: '+fpMoney(o.balance)+'. This moves existing credit; it does not record new cash.</p><label for="pr-credit-amount">Credit to apply ($)</label><input id="pr-credit-amount" type="number" min="0.01" max="'+Math.min(o.balance,prProfile.availableCredit)+'" step="0.01" value="'+Math.min(o.balance,prProfile.availableCredit).toFixed(2)+'" oninput="prInvalidate()">');
}
function prOpenPayment(row){
 const r=prFeed?.payments.find(p=>p.row===row);if(!r)return;
 drawerOpen=true;document.body.style.overflow='hidden';document.getElementById('drawer-backdrop').classList.add('open');document.getElementById('member-drawer').classList.add('open');document.getElementById('drawer-name').textContent=r.sender||r.name||'Payment review';document.getElementById('drawer-id').textContent='PAYMENTS row '+r.row;
 document.getElementById('drawer-body').innerHTML='<div class="fp-body"><p><strong>'+fpMoney(r.amount)+'</strong> · '+fpEscape(r.date)+'<br>'+fpEscape(r.status)+'<br>Memo: '+fpEscape(r.memo||'(none)')+'<br>Email: '+fpEscape(r.emailState||'NOT RECORDED')+' — '+fpEscape(r.emailStatus||'')+'<br>Notes: '+fpEscape(r.notes)+'</p>'+prProfileButton(r.memberId,'Open member profile')+'<div id="pr-action"></div></div>';
 prAction=null;prPreview=null;if(!r.canAllocate){document.getElementById('pr-action').textContent='This row cannot be allocated again. Confirmed/settled rows and reversal guards require separate investigation; no automatic reassignment.';return;}
 prAction={mode:'ALLOCATE',sourceRow:r.row,requestId:crypto.randomUUID()};
 prActionShell('Allocate this received payment','<div id="mw-payment-suggestions"></div><p>Enter the exact member and fund for every share. All shares must total '+fpMoney(r.amount)+'. Choose CREDIT explicitly for an agreed excess; do not guess from a surname.</p><div id="pr-lines"></div><button class="hero-btn secondary" onclick="prAddLine()">Add allocation</button>');prAddLine(r.memberId);mwPaymentSuggestions(r.row);document.getElementById('pr-action').insertAdjacentHTML('beforeend','<button class="hero-btn secondary" type="button" onclick="prStartDismiss()">Dismiss this unresolved payment</button>');
}
function prAddLine(memberId=''){
 const el=document.createElement('div');el.className='pr-line';el.style.cssText='padding:12px 0;border-bottom:1px solid var(--border)';
 el.innerHTML='<label>Member ID<input class="pr-mid" placeholder="MW0001" value="'+fpEscape(memberId)+'" oninput="prInvalidate()"></label><label>Fund code or CREDIT<select class="pr-code" onchange="prInvalidate()"><option value="">Choose fundraiser</option>'+fpFundDetails.map(f=>'<option value="'+fpEscape(f.code)+'">'+fpEscape(f.code+' — '+f.deceased)+'</option>').join('')+'<option value="CREDIT">Available funeral credit (explicit excess)</option></select></label><label>Amount ($)<input class="pr-amt" type="number" min="0.01" step="0.01" oninput="prInvalidate()"></label><button class="hero-btn secondary" onclick="this.parentNode.remove();prInvalidate()">Remove share</button>';
 document.getElementById('pr-lines').appendChild(el);prInvalidate();
}
function prPayload(){if(!prAction)throw Error('Choose an action');const p={mode:prAction.mode,sourceRow:prAction.sourceRow||0,requestId:prAction.requestId};if(prAction.mode==='DISMISS'){p.reason=document.getElementById('pr-dismiss-reason').value.trim();p.allocations=[];return p;}p.allocations=prAction.mode==='CREDIT'?[{memberId:prAction.memberId,fundCode:prAction.fundCode,amount:document.getElementById('pr-credit-amount').value}]:Array.from(document.querySelectorAll('.pr-line')).map(e=>({memberId:e.querySelector('.pr-mid').value.trim().toUpperCase(),fundCode:e.querySelector('.pr-code').value.trim().toUpperCase(),amount:e.querySelector('.pr-amt').value}));return p;}
async function prPreviewAction(){
 if(prBusy)return;prBusy=true;ftBusy=true;prInvalidate();const el=document.getElementById('pr-action-preview');el.textContent='Dry run…';
 try{const payload=prPayload(),d=await fpCall('fp_review_preview',payload);if(d.alreadyRecorded){el.textContent=d.message;return;}prPreview={payload,input:d.input,token:d.previewToken};el.textContent=d.message+(payload.mode==='DISMISS'?'\nWOULD DISMISS row '+payload.sourceRow+'; reason: '+payload.reason:'')+'\n'+d.plan.allocations.map(a=>a.memberId+' '+a.fundCode+' '+fpMoney(a.amount)+(a.newBalance!==undefined?' → remaining '+fpMoney(a.newBalance):' added as available credit')+(a.lateFeeAssessed?' | includes assessment of $5 late fee':'')).join('\n')+'\nTarget cells: '+d.plan.targets.map(t=>t.sheet+' row '+t.row+' column '+t.column).join('; ');document.getElementById('pr-apply').disabled=false;}
 catch(e){el.textContent=e.message;}finally{prBusy=false;ftBusy=false;}
}
async function prApplyAction(){
 if(prBusy||!prPreview)return;
 if(JSON.stringify(prPayload())!==JSON.stringify(prPreview.payload)){prInvalidate();return;}
 if(!confirm('Apply only the allocations shown in the dry run? This changes the specified ledger/tracker/credit records. A confirmation email will be sent after completion.'))return;
 const refreshMember=prAction?.mode==='CREDIT'?prAction.memberId:'';let applied=false;
 prBusy=true;ftBusy=true;const el=document.getElementById('pr-action-preview');document.getElementById('pr-apply').disabled=true;
 try{const d=await fpCall('fp_review_apply',{...prPreview.input,previewToken:prPreview.token,confirmed:'YES'});el.textContent=d.message;applied=true;prPreview=null;prAction=null;prMessage('Action recorded. Refresh payments and the member profile to verify.');}
 catch(e){el.textContent=e.message+' Keep the same request. Do not create a new request to bypass a hold.';document.getElementById('pr-apply').disabled=false;}finally{prBusy=false;ftBusy=false;}
 if(applied){if(typeof showToast==='function')showToast('Approved payment action recorded. Refreshing records.',5000);await prLoad(prOffset);if(refreshMember)await openDrawer(refreshMember,'');}
}
function prCancelAction(){if(prBusy)return;prAction=null;prPreview=null;document.getElementById('pr-action').replaceChildren();}
async function prResume(){if(prBusy||!prFeed?.pendingAction)return;if(!confirm('Resume the previously approved request '+prFeed.pendingAction+'? Changed target cells will stop the operation for review.'))return;prBusy=true;ftBusy=true;try{const d=await fpCall('fp_review_resume',{requestId:prFeed.pendingAction,confirmed:'YES'});prMessage(d.message);}catch(e){prMessage(e.message,true);}finally{prBusy=false;ftBusy=false;}}
runMemberLookup=function(){
 const query=document.getElementById('lookup-input').value.trim().toLowerCase(),el=document.getElementById('lookup-results');
 if(!query){el.textContent='Enter a member ID or name.';return;}
 const matches=allMembers.filter(m=>[m.id,m.name,m.email].some(v=>String(v||'').toLowerCase().includes(query)));
 if(matches.length===1){openDrawer(matches[0].id,matches[0].name);return;}
 el.innerHTML=matches.slice(0,20).map(m=>'<div style="margin:8px 0">'+prProfileButton(m.id,m.name+' ('+m.id+')')+'</div>').join('')||'No matching member found.';
};
let mwMailOffset=0,mwMailPreview=null,mwNoticePreview=null,mwNoticeBusy=false,mwMailBusy=false,mwNotices=null;
const MW_NOTICE_HTML=`<section class="card fp-panel" id="sec-notice-review"><div class="card-header"><span class="card-title">Five or more missed funds</span></div><div class="fp-body"><p>Review overdue obligations, inspect each member and select who should receive a seven-day warning. This does not remove memberships.</p><div class="fp-actions"><button class="hero-btn secondary" onclick="mwNoticeLoad()">Refresh review list</button></div><div id="mw-notice-list"></div><label for="mw-notice-deadline">Warning deadline</label><input type="date" id="mw-notice-deadline" onchange="mwNoticeInvalidate()"><div class="fp-actions"><button class="hero-btn secondary" onclick="mwNoticePreviewSelected()">Preview selected emails</button><button class="hero-btn primary" id="mw-notice-send" disabled onclick="mwNoticeSend()">Confirm and send selected warnings</button></div><div id="mw-notice-status" role="status"></div><div id="mw-notice-preview"></div></div></section>`;
const MW_MAIL_HTML=`<details id="mw-bank-emails"><summary>Bank emails not yet recorded</summary><p>Inspect bank notices before staging them for allocation. Possible existing or split transactions stay on hold.</p><label for="mw-mail-days">Review period</label><select id="mw-mail-days"><option value="TODAY">Today</option><option value="YESTERDAY">Yesterday</option><option value="THIS_WEEK" selected>This week</option><option value="LAST_WEEK">Last week</option><option value="THIS_MONTH">This month</option><option value="CUSTOM">Custom dates</option></select><div class="fp-fields"><div><label for="mw-mail-start">Custom start</label><input id="mw-mail-start" type="date"></div><div><label for="mw-mail-end">Custom end</label><input id="mw-mail-end" type="date"></div></div><div class="fp-actions"><button class="hero-btn secondary" onclick="mwMailLoad(0)">Read bank emails</button><button class="hero-btn primary" onclick="mwRunInspection()">Inspect payments for this period</button><button class="hero-btn secondary" id="mw-mail-next" disabled onclick="mwMailLoad(mwMailOffset+50)">Next conversations</button></div><div id="mw-mail-status" role="status"></div><div id="mw-mail-list"></div><div id="mw-mail-preview"></div></details>`;
function mwNoticeInvalidate(){mwNoticePreview=null;const b=document.getElementById('mw-notice-send');if(b)b.disabled=true;}
async function mwMailLoad(offset=0){
 if(mwMailBusy)return;mwMailBusy=true;ftBusy=true;const status=document.getElementById('mw-mail-status');status.textContent='Reading bank emails…';
 try{const d=await fpCall('fp_ops_mail',{offset,period:document.getElementById('mw-mail-days').value,start:document.getElementById('mw-mail-start').value,end:document.getElementById('mw-mail-end').value});mwMailOffset=d.offset;document.getElementById('mw-mail-next').disabled=d.nextOffset===null;
 document.getElementById('mw-mail-list').innerHTML=prTable(['Received / bank transaction','Sender / memo','Amount','Review','Action'],d.messages.map(m=>[
 fpEscape(m.date)+'<br>'+fpEscape(m.transactionId||'No transaction number extracted'),fpEscape(m.sender||'Review original email')+'<br>'+fpEscape(m.memo||''),m.amount===undefined?'—':fpMoney(m.amount),fpEscape(m.error||(m.check.canStage?'No matching ledger source found':m.check.reasons.join(' '))),
 '<a target="_blank" rel="noopener noreferrer" href="https://mail.google.com/mail/u/0/#all/'+encodeURIComponent(m.messageId)+'">Open email</a>'+(m.check?.canStage?'<br><button class="hero-btn secondary" onclick="mwMailStagePreview(\''+fpEscape(m.messageId)+'\')">Preview staging</button>':'')
 ]));status.textContent=d.message;
 }catch(e){status.textContent=e.message;}finally{mwMailBusy=false;ftBusy=false;}
}
async function mwMailStagePreview(messageId){
 if(mwMailBusy)return;mwMailBusy=true;ftBusy=true;mwMailPreview=null;const el=document.getElementById('mw-mail-preview');el.textContent='Validating source and duplicate checks…';
 try{const payload={messageId,requestId:crypto.randomUUID()},d=await fpCall('fp_ops_stage_preview',payload);if(d.alreadyRecorded){el.textContent=d.message+' PAYMENTS row '+d.row;return;}mwMailPreview={payload,token:d.previewToken};el.innerHTML='<div class="fp-note">'+fpEscape(d.message)+'<br>'+fpEscape(d.source.sender)+' · '+fpMoney(d.source.amount)+'<br>Memo: '+fpEscape(d.source.memo)+'</div><button class="hero-btn primary" onclick="mwMailStageApply()">Confirm staging for review</button>';
 }catch(e){el.textContent=e.message;}finally{mwMailBusy=false;ftBusy=false;}
}
async function mwMailStageApply(){
 if(mwMailBusy||!mwMailPreview)return;if(!confirm('Stage this bank email as one UNMATCHED source for manual allocation? No fund payment is applied at this step.'))return;
 mwMailBusy=true;ftBusy=true;const el=document.getElementById('mw-mail-preview');try{const d=await fpCall('fp_ops_stage_apply',{...mwMailPreview.payload,previewToken:mwMailPreview.token,confirmed:'YES'});el.textContent=d.message;mwMailPreview=null;document.getElementById('pr-filter').value='REVIEW';await prLoad(0);}catch(e){el.textContent=e.message+' Inspect before starting a different request.';}finally{mwMailBusy=false;ftBusy=false;}
}
async function mwNoticeLoad(){
 if(mwNoticeBusy)return;mwNoticeBusy=true;ftBusy=true;mwNoticeInvalidate();const el=document.getElementById('mw-notice-status');el.textContent='Checking fund-specific overdue balances…';
 try{mwNotices=await fpCall('fp_ops_notices');document.getElementById('mw-notice-list').innerHTML=prTable(['Select','Member','Missed','Outstanding','Review state'],mwNotices.members.map(m=>[
 '<input type="checkbox" class="mw-notice-member" value="'+fpEscape(m.memberId)+'" aria-label="Select '+fpEscape(m.name)+'" '+(m.canSend?'':'disabled')+' onchange="mwNoticeInvalidate()">',prProfileButton(m.memberId,m.name)+'<br>'+fpEscape(m.email),String(m.missed),fpMoney(m.total),fpEscape(m.blocked.join('; ')||'Ready for your review · '+m.decision)+'<br>'+m.obligations.map(o=>fpEscape(o.fundCode)+' '+fpMoney(o.balance)).join(' · ')]));
 el.textContent=mwNotices.message+(mwNotices.warnings.length?' '+mwNotices.warnings.join('; '):'');const date=document.getElementById('mw-notice-deadline');if(!date.value){const day=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+7);date.value=d.toISOString().slice(0,10);}
 }catch(e){el.textContent=e.message;}finally{mwNoticeBusy=false;ftBusy=false;}
}
function mwNoticeInput(){return {memberIds:Array.from(document.querySelectorAll('.mw-notice-member:checked')).map(e=>e.value),deadline:document.getElementById('mw-notice-deadline').value};}
async function mwNoticePreviewSelected(){
 if(mwNoticeBusy)return;mwNoticeBusy=true;ftBusy=true;mwNoticeInvalidate();const el=document.getElementById('mw-notice-preview');el.textContent='Preparing warning previews…';
 try{const payload=mwNoticeInput(),d=await fpCall('fp_ops_notice_preview',payload);mwNoticePreview={payload,token:d.previewToken};el.innerHTML='<p>'+fpEscape(d.message)+'</p>'+d.messages.map(m=>'<details><summary>'+fpEscape(m.memberId)+' · '+fpEscape(m.email)+' · '+m.missed+' missed · '+fpMoney(m.total)+'</summary><h4>'+fpEscape(m.subject)+'</h4><pre class="mw-email-preview">'+fpEscape(m.text)+'</pre></details>').join('');document.getElementById('mw-notice-send').disabled=false;
 }catch(e){el.textContent=e.message;}finally{mwNoticeBusy=false;ftBusy=false;}
}
async function mwNoticeSend(){
 if(mwNoticeBusy||!mwNoticePreview)return;if(JSON.stringify(mwNoticeInput())!==JSON.stringify(mwNoticePreview.payload)){mwNoticeInvalidate();return;}
 if(!confirm('Send only the '+mwNoticePreview.payload.memberIds.length+' warning emails shown in the preview? No memberships will be removed.'))return;
 mwNoticeBusy=true;ftBusy=true;const el=document.getElementById('mw-notice-status');try{const d=await fpCall('fp_ops_notice_send',{...mwNoticePreview.payload,previewToken:mwNoticePreview.token,confirmed:'YES'});el.textContent=d.message+' '+d.results.map(x=>x.memberId+': '+x.status+(x.message?' — '+x.message:'')).join('; ');mwNoticeInvalidate();}catch(e){el.textContent=e.message+' Check the notice audit before retrying.';}finally{mwNoticeBusy=false;ftBusy=false;}
}
