let mwAdminBusy=false,mwAdminPreview=null;const mwRosters={};
function mwProfileStanding(d){const s=d.adminStatus;if(!s)return '<div class="fp-note">Standing verification is unavailable. Check registration, arrears and declaration timing before approving benefits.</div>';return '<div class="mw-role-badges">'+s.roles.map(r=>'<span>'+fpEscape(r.body)+' · '+fpEscape(r.position)+'</span>').join('')+'</div><div class="mw-standing '+(s.overdueFunds||s.standing!=='CURRENT'?'mw-standing-alert':'')+'"><strong>'+fpEscape(s.displayStatus)+'</strong><p>'+s.overdueFunds+' overdue fund(s) · '+s.ongoingUnpaidFunds+' ongoing fund(s) awaiting payment</p><p>Benefits: '+fpEscape(s.benefits)+'</p><small>Registration: '+fpMoney(s.registrationPaid)+' / '+fpMoney(s.registrationRequired)+'</small></div>';}
async function mwFundRoster(code,target){const el=document.getElementById(target);if(!el)return;el.textContent='Reading this fund’s paid and unpaid members…';ftBusy=true;try{const d=await fpCall('fp_review_fund',{fundCode:code});if(!document.getElementById(target))return;if(target==='fp-fund-roster'&&document.getElementById('fp-fund').value!==code)return;mwRosters[target]={data:d,filter:'ALL'};mwRenderRoster(target);}catch(e){el.textContent='Fund member list: '+e.message;}finally{ftBusy=false;}}
function mwRenderRoster(target){const item=mwRosters[target],el=document.getElementById(target);if(!item||!el)return;const d=item.data,s=d.stats||{},filter=item.filter;
 const rows=d.members.filter(m=>filter==='ALL'||(filter==='PAID'&&/^(PAID|COVERED BY CREDIT)$/.test(m.status))||(filter==='UNPAID'&&m.status!=='EXEMPT'&&m.balance>0)||(filter==='REVIEW'&&m.status==='REVIEW'));
 el.innerHTML='<h3 style="margin:24px 0 12px">'+fpEscape(d.fund.code)+' · Paid &amp; unpaid members</h3><div class="mw-review-stats"><div class="mw-review-stat"><span>Members · '+Number(s.exempt||0)+' exempt</span><strong>'+Number(s.rows||0)+'</strong></div><div class="mw-review-stat"><span>Paid / credit-covered · unpaid</span><strong>'+Number(s.paid||0)+' / '+Number(s.unpaid||0)+'</strong></div><div class="mw-review-stat mw-review-confirmed"><span>Recorded fund contributions</span><strong>'+fpMoney(s.confirmedCash)+'</strong></div></div><p>'+Number(s.review||0)+' records need review · '+fpMoney(s.outstanding)+' outstanding</p><div class="fp-actions"><select aria-label="Filter fund members" onchange="mwRosters[\''+target+'\'].filter=this.value;mwRenderRoster(\''+target+'\')"><option value="ALL">All fund members</option><option value="PAID">Paid / credit-covered</option><option value="UNPAID">Unpaid / partial</option><option value="REVIEW">Needs review</option></select><button class="hero-btn secondary" type="button" onclick="mwDownloadRoster(\''+target+'\')">Download this fund CSV</button></div>'+prTable(['Member','Status','Paid','Credit applied','Outstanding','Payment dates','Issues'],rows.map(m=>[m.formerMember?fpEscape(m.name)+'<br><small>Former member</small>':prProfileButton(m.memberId,m.name),fpEscape(m.status),fpMoney(m.paid),fpMoney(m.creditApplied),m.balance===null?'Review':fpMoney(m.balance),(m.paymentDates||[]).map(fpEscape).join('<br>')||(m.creditApplied>0?'Covered by applied credit':'No recorded fund payment'),(m.issues||[]).map(fpEscape).join('<br>')]));el.querySelector('select').value=filter;}
function mwDownloadRoster(target){const d=mwRosters[target]?.data;if(!d)return;function cell(v){let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}const rows=[['Fund','Member ID','Member name','Status','Paid','Credit applied','Outstanding','Payment dates','Issues'],...d.members.map(m=>[d.fund.code,m.memberId,m.name,m.status,m.paid,m.creditApplied,m.balance,(m.paymentDates||[]).join('; '),(m.issues||[]).join('; ')])];const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=d.fund.code+'-paid-unpaid-members.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function mwPaymentSuggestions(row){const el=document.getElementById('mw-payment-suggestions');if(!el)return;el.textContent='Checking memo hints…';try{const d=await fpCall('fp_admin_suggest',{sourceRow:row});if(!document.getElementById('mw-payment-suggestions'))return;el.innerHTML='<div class="fp-note"><strong>Memo hints · verify before using</strong><p>Exact member IDs: '+fpEscape(d.memberIds.join(', ')||'None found')+'<br>Possible IDs: '+fpEscape(d.possibleMemberIds.join(', ')||'None')+'<br>Fund references: '+fpEscape(d.fundCodes.join(', ')||'None found')+(d.creditMention?'<br>Memo mentions future payments or credit. Confirm the exact remaining amount.':'')+'</p>'+fpEscape(d.message)+'</div>';}catch(e){el.textContent=e.message;}}
const MW_ADMIN_UI=`<section class="card fp-panel" id="sec-admin-workflows"><div class="card-header"><span class="card-title">Guided administration</span></div><div class="fp-body"><p>Choose a task, check its requirements, preview the exact impact, then confirm. Nothing runs automatically from this screen.</p><label for="mw-admin-task">What do you need to do?</label><select id="mw-admin-task" onchange="mwAdminChange()"><option value="REMINDERS">Send consolidated payment reminders</option><option value="LATE_APPLY">Apply overdue late fees to selected members</option><option value="LATE_REVERSE">Reverse a verified unpaid late fee</option><option value="CLEANUP">Clean up already-removed members from pending fund lists</option><option value="REMOVE">Remove selected members after approved final-notice review</option><option value="BOARD_BADGES">Record confirmed Board member badges</option><option value="SLIDES">Prepare fund slides for a meeting</option><option value="OPEN_FUND">Open a verified funeral fund</option></select><div class="fp-note" id="mw-admin-help"></div><div id="mw-admin-members-wrap"><label for="mw-admin-members">Member IDs (comma separated, maximum 20)</label><input id="mw-admin-members" placeholder="MW0001, MW0200" oninput="mwAdminInvalidate()"></div><div id="mw-admin-fund-wrap"><label for="mw-admin-fund">Fundraiser</label><select id="mw-admin-fund" onchange="mwAdminInvalidate()"></select></div><div id="mw-admin-reason-wrap"><label for="mw-admin-reason">Reason for this correction</label><input id="mw-admin-reason" oninput="mwAdminInvalidate()"></div><div id="mw-admin-board-wrap"><label for="mw-admin-board">Board approval / case reference</label><input id="mw-admin-board" oninput="mwAdminInvalidate()"><label><input id="mw-admin-case" type="checkbox" onchange="mwAdminInvalidate()"> I confirm the required Board/Welfare verification, including the member’s opportunity to present their case for removal.</label></div><div id="mw-admin-open-wrap"><label for="mw-admin-deceased">Deceased’s declared full name</label><input id="mw-admin-deceased" oninput="mwAdminInvalidate()"><label for="mw-admin-relationship">Relationship</label><select id="mw-admin-relationship" onchange="mwAdminInvalidate()"><option>Father</option><option>Mother</option><option>Spouse</option><option>Child</option><option>Sibling</option><option>Self</option></select><label for="mw-admin-amount">Contribution per member</label><input id="mw-admin-amount" type="number" min="10" value="10" oninput="mwAdminInvalidate()"><label for="mw-admin-deadline">Contribution deadline</label><input id="mw-admin-deadline" type="date" onchange="mwAdminInvalidate()"><label for="mw-admin-evidence">Verification reference: declaration and payment confirmed before loss</label><input id="mw-admin-evidence" oninput="mwAdminInvalidate()"></div><div id="mw-admin-position-wrap"><label for="mw-admin-position">Board position</label><input id="mw-admin-position" value="Board Member" oninput="mwAdminInvalidate()"></div><div class="fp-actions"><button class="hero-btn secondary" onclick="mwAdminPreviewTask()">1. Dry run / preview</button><button id="mw-admin-confirm" disabled class="hero-btn primary" onclick="mwAdminConfirmTask()">2. Confirm this task</button></div><div id="mw-admin-status" role="status"></div><div id="mw-admin-preview"></div></div></section>`;
function mwAdminPrepare(){const sel=document.getElementById('mw-admin-fund');if(!sel)return;const current=sel.value;sel.replaceChildren(new Option('Select a fund',''));fpFundDetails.forEach(f=>sel.add(new Option(f.code+' — '+f.deceased,f.code)));sel.value=current;mwAdminChange();}
function mwAdminInvalidate(){mwAdminPreview=null;const b=document.getElementById('mw-admin-confirm');if(b)b.disabled=true;}
function mwAdminChange(){mwAdminInvalidate();const task=document.getElementById('mw-admin-task').value;const visibility={'members':!['CLEANUP','SLIDES'].includes(task),'fund':['LATE_APPLY','LATE_REVERSE'].includes(task),'reason':['LATE_APPLY','LATE_REVERSE'].includes(task),'board':['REMOVE','OPEN_FUND'].includes(task),'open':task==='OPEN_FUND','position':task==='BOARD_BADGES'};Object.entries(visibility).forEach(([name,show])=>document.getElementById('mw-admin-'+name+'-wrap').hidden=!show);const help={BOARD_BADGES:'Use only the confirmed Board roster. Display badges do not grant payment access or contribution exemptions.',REMINDERS:'One consolidated email per selected member, listing their outstanding funds. Review the full email first. Same-day logged reminders are held.',LATE_APPLY:'Only overdue, non-exempt balances with no fee already assessed can be charged. Preview lists the exact balances before and after.',LATE_REVERSE:'Only a verified unpaid $5 fee can be reversed. Paid fees need a separate refund/credit review.',CLEANUP:'For people already removed with a dated removal record and absent from MEMBERS. Paid or credit-covered historical TRACK rows are retained to protect fund totals.',REMOVE:'Requires a sent final notice, passed deadline, remaining notified arrears and recorded Board approval. This is not automatic removal based solely on a missed-fund count.',SLIDES:'Runs your existing fund-slides generator. It creates a Google Slides deck and sends its link to leadership.',OPEN_FUND:'Verify registration, declaration timing and Welfare/Board evidence. A previous/possible claim stops creation. Existing fund creation also applies stored credit; every effect is listed in the preview.'};document.getElementById('mw-admin-help').textContent=help[task];}
function mwAdminInput(){const value=id=>document.getElementById('mw-admin-'+id).value.trim();return {task:value('task'),requestId:mwAdminPreview?.input.requestId||crypto.randomUUID(),memberIds:value('members').toUpperCase().split(/[\s,;]+/).filter(Boolean),fundCode:value('fund'),reason:value('reason'),boardReference:value('board'),caseReviewed:document.getElementById('mw-admin-case').checked?'YES':'NO',deceased:value('deceased'),relationship:value('relationship'),deadline:value('deadline'),amount:value('amount'),evidence:value('evidence'),position:value('position')};}
async function mwAdminPreviewTask(){if(mwAdminBusy)return;mwAdminBusy=true;ftBusy=true;const el=document.getElementById('mw-admin-preview');mwAdminInvalidate();el.textContent='Checking current records and requirements…';try{const input=mwAdminInput(),d=await fpCall('fp_admin_preview',input);mwAdminPreview={input,token:d.previewToken};el.innerHTML='<div class="fp-note"><strong>'+fpEscape(d.summary)+'</strong><p>'+fpEscape(d.message)+'</p></div>'+mwAdminDetails(d.details);document.getElementById('mw-admin-confirm').disabled=false;}catch(e){el.textContent=e.message;}finally{mwAdminBusy=false;ftBusy=false;}}
function mwAdminDetails(d){if(d.messages)return d.messages.map(m=>'<details><summary>'+fpEscape(m.group.id)+' · '+fpEscape(m.group.email)+' · '+fpMoney(m.group.totalDue)+'</summary><pre class="mw-email-preview">'+fpEscape(m.text)+'</pre></details>').join('');if(d.operations)return prTable(['Sheet','Row','Column','Before','After'],d.operations.map(o=>[fpEscape(o.sheet),String(o.row),String(o.col),fpEscape(JSON.stringify(o.before)),fpEscape(JSON.stringify(o.after))]));if(d.targets)return prTable(['Member','Fund tracker','Row','Action'],d.targets.map(t=>[fpEscape(t.memberId),fpEscape(t.sheet),String(t.row),'Archive then remove unpaid row']))+'<p>'+d.held.length+' paid/credit history rows retained.</p>';if(d.members)return prTable(['Member','Name','Notified arrears','Approval'],d.members.map(m=>[fpEscape(m.memberId),fpEscape(m.name),m.balance?fpMoney(m.balance.total):'Display badge only',fpEscape(d.boardReference||d.position||'')]));if(d.creditEffects)return prTable(['Member','Stored credit to be applied'],d.creditEffects.map(x=>[fpEscape(x.memberId),fpMoney(x.amount)]))+'<p>Deceased: '+fpEscape(d.deceased)+' · Claimant '+fpEscape(d.claimant)+' · Deadline '+fpEscape(d.deadline)+'</p>';if(d.funds)return '<ul>'+d.funds.map(f=>'<li>'+fpEscape(f.code+' — '+f.deceased)+'</li>').join('')+'</ul>';return '';}
async function mwAdminConfirmTask(){if(mwAdminBusy||!mwAdminPreview)return;const preview=mwAdminPreview,current=mwAdminInput();if(JSON.stringify(current)!==JSON.stringify(preview.input)){mwAdminInvalidate();return;}if(!confirm('Carry out only the task and effects shown in the dry run? This may change records or send the selected emails.'))return;mwAdminBusy=true;ftBusy=true;document.getElementById('mw-admin-confirm').disabled=true;const el=document.getElementById('mw-admin-status');el.textContent='Applying the confirmed task…';try{const d=await fpCall('fp_admin_apply',{...preview.input,previewToken:preview.token,confirmed:'YES'});el.textContent=d.message;document.getElementById('mw-admin-preview').textContent=JSON.stringify(d.result,null,2);mwAdminPreview=null;}catch(e){el.textContent=e.message+' Keep this request and inspect its audit before starting another.';}finally{mwAdminBusy=false;ftBusy=false;}}
async function prInspectSource(row){try{const d=await fpCall('fp_review_source',{sourceRow:row});if(!prFeed)prFeed={payments:[]};prFeed.payments=prFeed.payments.filter(x=>x.row!==row).concat(d.payment);prOpenPayment(row);}catch(e){prMessage(e.message,true);}}
async function mwRunInspection(offset=0){if(mwMailBusy)return;mwMailBusy=true;ftBusy=true;const el=document.getElementById('mw-mail-list'),status=document.getElementById('mw-mail-status');status.textContent='Inspecting individual bank messages against recorded rows…';try{const d=await fpCall('fp_admin_inspect',{period:document.getElementById('mw-mail-days').value,start:document.getElementById('mw-mail-start').value,end:document.getElementById('mw-mail-end').value,offset});el.innerHTML=(d.nextOffset===null?'':'<button class="hero-btn secondary" onclick="mwRunInspection('+d.nextOffset+')">Inspect next conversations</button>')+'<div class="mw-review-stats"><div class="mw-review-stat"><span>Recorded candidates</span><strong>'+d.stats.recorded+'</strong></div><div class="mw-review-stat"><span>Missing / review</span><strong>'+d.stats.missing+'</strong></div><div class="mw-review-stat"><span>Other review</span><strong>'+d.stats.review+'</strong></div></div>'+prTable(['Status / source','Memo','Finding','Actions'],d.items.map(m=>[fpEscape(m.auditStatus)+'<br>'+fpEscape(m.sender||'')+' '+(m.amount===undefined?'':fpMoney(m.amount)),fpEscape(m.memo||''),fpEscape(m.finding),'<a target="_blank" rel="noopener noreferrer" href="https://mail.google.com/mail/u/0/#all/'+encodeURIComponent(m.messageId)+'">Open bank email</a><br>'+(m.candidateRows||[]).map(r=>'<button class="hero-btn secondary" onclick="prInspectSource('+r.row+')">Inspect ledger row '+r.row+'</button>').join(' ')+(m.check?.canStage?'<button class="hero-btn secondary" onclick="mwMailStagePreview(\''+fpEscape(m.messageId)+'\')">Preview missing-source staging</button>':'') ]));status.textContent=d.message+(d.nextOffset===null?'':' More conversations remain; use the bank-email pages for the complete period.');}catch(e){status.textContent=e.message;}finally{mwMailBusy=false;ftBusy=false;}}
const MW_ADMIN_CSS=`#sec-overview{display:grid!important;margin-bottom:24px}.mw-light .stat-card{background:#fff!important;border:1px solid #d5dfec!important;box-shadow:0 3px 12px #17365706}.mw-light .stat-card .stat-label,.mw-light .stat-card .stat-sub{color:#526983!important}.mw-light .stat-card .stat-value{color:#1b4a2d}.mw-light .stat-card.red .stat-value{color:#b22e29}.mw-light .stat-card.gold .stat-value{color:#865600}.mw-light .stat-card.navy .stat-value{color:#183650}.mw-light .stat-card span{color:#34506d!important}.mw-light .fp-body select{background-repeat:no-repeat!important;background-position:right 12px center!important;background-size:18px 18px!important}.mw-light .btn-refresh,.mw-light .hero-btn.primary,.mw-light .hero-btn.teal,.mw-light .hero-btn.purple{color:#fff!important}.mw-light .hero-btn.secondary{background-color:#f1f5fa;color:#23405f!important;border-color:#c5d3e4}.mw-light .fp-body{color:#203954}.mw-light input::placeholder{color:#657c95}.mw-role-badges{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px}.mw-role-badges span{padding:7px 11px;border-radius:7px;border:1px solid #a8d88044;background:#217b3122;font-size:13px;font-weight:700;color:var(--gmid)}.mw-standing{border:1px solid #80b87855;background:#217b3119;border-radius:10px;padding:18px;margin-bottom:18px}.mw-standing>strong{font-size:18px;color:var(--gmid)}.mw-standing-alert{border-color:#d68b0c66;background:#d68b0c10}.mw-standing-alert>strong{color:#efbc60}.mw-light .mw-standing-alert>strong{color:#8b5b07}.mw-standing p{margin:8px 0!important;font-size:14px!important}.mw-standing small{font-size:13px}#sec-admin-workflows [hidden]{display:none!important}#mw-admin-preview,#mw-admin-status{white-space:pre-wrap;font-size:14px;line-height:1.7;margin-top:16px}#mw-admin-board-wrap input[type=checkbox]{width:20px;min-height:20px;vertical-align:middle;margin-right:8px}.pr-line{display:grid;grid-template-columns:1fr 1.5fr .7fr auto;align-items:end;gap:10px}@media(max-width:800px){.pr-line{grid-template-columns:1fr 1fr}#sec-overview{grid-template-columns:repeat(2,1fr)}}`;

let mwOverviewBusy=false;
const MW_OVERVIEW_HTML=`<section class="card fp-panel" id="sec-dashboard-overview"><div class="card-header"><span class="card-title">Operations overview</span><button class="hero-btn secondary" onclick="mwLoadOverview()">Refresh overview</button></div><div class="fp-body"><div id="mw-overview-content">Loading your operational summary…</div></div></section>`;
function mwGoTask(task){mwSelectWorkspace('admin');mwAdminPrepare();document.getElementById('mw-admin-task').value=task;mwAdminChange();}
async function mwOpenFundSummary(code){mwSelectWorkspace('payouts');const select=document.getElementById('fp-fund');select.value=code;if(select.value!==code){await fpLoadFunds();select.value=code;}await fpLoadBalance();}
async function mwLoadOverview(){if(mwOverviewBusy)return;mwOverviewBusy=true;ftBusy=true;const el=document.getElementById('mw-overview-content');if(!el){mwOverviewBusy=false;ftBusy=false;return;}try{const d=await fpCall('fp_admin_overview'),peak=Math.max(1,...d.weeklyTrend.map(x=>x.amount)),fundPeak=Math.max(1,...d.funds.map(f=>f.collected)),emailTotal=d.recordedEmailSent+d.otherEmailStates,percent=emailTotal?Math.round(d.recordedEmailSent/emailTotal*100):0;
 el.innerHTML='<p>As of '+fpEscape(d.generatedAt)+'</p><div class="mw-overview-metrics">'+[['Members',Number(d.members).toLocaleString()],['Confirmed funeral contributions',fpMoney(d.confirmedFuneralCash)],['Available member credit',fpMoney(d.availableCredit)],['Payment rows needing review',Number(d.needsReview).toLocaleString()]].map(([l,v])=>'<div class="mw-review-stat"><span>'+fpEscape(l)+'</span><strong>'+fpEscape(v)+'</strong></div>').join('')+'</div><div class="mw-overview-charts"><section><h3>Contributions · last seven days</h3><div class="mw-daily-bars">'+d.weeklyTrend.map(x=>'<div><span>'+fpMoney(x.amount)+'</span><div class="mw-daily-track"><i style="height:'+Math.max(x.amount?3:0,Math.round(x.amount/peak*100))+'%"></i></div><small>'+fpEscape(x.date.slice(5))+'</small></div>').join('')+'</div></section><section><h3>Receipt email status</h3><div class="mw-email-ring" style="background:conic-gradient(#217B31 0% '+percent+'%,var(--card2) '+percent+'% 100%)"><div><strong>'+percent+'%</strong><span>Recorded sent</span></div></div><p>'+d.recordedEmailSent+' recorded sent · '+d.otherEmailStates+' not sent / other states</p><small>A sent flag does not establish delivery or that the email was read.</small></section></div><div class="mw-overview-charts"><section><h3>Confirmed contributions by fund</h3>'+d.funds.map(f=>'<button class="mw-fund-chart-row" onclick="mwOpenFundSummary(\''+fpEscape(f.code)+'\')"><span>'+fpEscape(f.code)+' <strong>'+fpMoney(f.collected)+'</strong></span><i><b style="width:'+Math.round(f.collected/fundPeak*100)+'%"></b></i><small>'+fpEscape(f.deceased)+'</small></button>').join('')+'</section><section><h3>Daily work · start here</h3><div class="mw-workflow-links"><button class="hero-btn secondary" onclick="mwSelectWorkspace(\'payments\');prShowZelleReview()">Review Zelle payments</button><button class="hero-btn secondary" onclick="mwGoTask(\'REMINDERS\')">Send consolidated reminders</button><button class="hero-btn secondary" onclick="mwGoTask(\'LATE_APPLY\')">Review late fees</button><button class="hero-btn secondary" onclick="mwGoTask(\'SLIDES\')">Prepare meeting slides</button><button class="hero-btn secondary" onclick="mwGoTask(\'OPEN_FUND\')">Open a verified fund</button><button class="hero-btn secondary" onclick="mwGoTask(\'CLEANUP\')">Clean up removed members</button></div><p>Every administrative workflow starts with a dry run. Existing financial records are never rebuilt automatically.</p></section></div><h3 style="margin-top:24px">Recent dashboard actions</h3>'+prTable(['Time','Origin','Action','Outcome','Reference'],d.activity.map(a=>[fpEscape(a.at),fpEscape(a.origin),fpEscape(a.action),fpEscape(a.outcome),fpEscape(a.requestId)]))+(!d.activity.length?'<p>Actions will appear here after confirmed dashboard changes. Earlier actions remain in their original audit sheets.</p>':'')+'<p style="font-size:13px;margin-top:18px">'+fpEscape(d.note)+'</p>';
 }catch(e){el.textContent=e.message;}finally{mwOverviewBusy=false;ftBusy=false;}}
const MW_OVERVIEW_CSS=`.mw-overview-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:18px 0}.mw-overview-charts{display:grid;grid-template-columns:1.25fr 1fr;gap:18px;margin-top:18px}.mw-overview-charts>section{padding:20px;border:1px solid var(--border);border-radius:12px;background:var(--card2)}.mw-overview-charts h3{font-size:16px;margin-bottom:18px}.mw-daily-bars{display:flex;align-items:flex-end;justify-content:space-around;gap:8px;height:215px}.mw-daily-bars>div{display:flex;flex:1;min-width:0;flex-direction:column;align-items:center;gap:8px;height:100%}.mw-daily-bars span{font-size:11px;white-space:nowrap}.mw-daily-track{height:160px;width:28px;display:flex;align-items:flex-end;border-radius:6px;background:var(--navy2);overflow:hidden}.mw-daily-track i{display:block;width:100%;background:linear-gradient(#a8d880,#217b31);border-radius:5px}.mw-daily-bars small{font-size:12px;color:var(--text2)}.mw-email-ring{margin:10px auto 20px;width:145px;height:145px;border-radius:50%;padding:18px}.mw-email-ring>div{height:100%;border-radius:50%;background:var(--card);display:flex;flex-direction:column;align-items:center;justify-content:center}.mw-email-ring strong{font-size:27px}.mw-email-ring span{font-size:11px;color:var(--text2)}.mw-fund-chart-row{display:block;width:100%;border:0;background:none;color:var(--text);text-align:left;padding:10px 0;cursor:pointer}.mw-fund-chart-row>span{display:flex;justify-content:space-between;font:600 13px 'DM Sans',sans-serif}.mw-fund-chart-row>i{display:block;height:6px;background:var(--navy2);border-radius:5px;margin:9px 0;overflow:hidden}.mw-fund-chart-row b{display:block;height:6px;background:#217b31}.mw-fund-chart-row small{color:var(--text2);font-size:12px}.mw-workflow-links{display:grid;gap:10px;margin-bottom:20px}.mw-workflow-links button{text-align:left}.mw-overview-charts p{font-size:14px!important}.mw-overview-charts small{font-size:12px;color:var(--text2)}@media(max-width:1200px){.mw-overview-metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:680px){.mw-overview-charts{grid-template-columns:1fr}.mw-daily-track{width:23px}.mw-daily-bars{gap:4px}.mw-overview-metrics .mw-review-stat strong{font-size:20px}}`;

(function mountPaymentReview(){
 const opsStyle=document.createElement('style');opsStyle.textContent=MW_OPERATIONS_CSS+MW_ADMIN_CSS+MW_OVERVIEW_CSS;document.head.appendChild(opsStyle);
 const previousBusy=isFixToolBusy;isFixToolBusy=function(){const section=document.getElementById('sec-payment-review');return mwStatementBusy||!!mwStatementPreview||prBusy||mwOverviewBusy||mwAdminBusy||!!mwAdminPreview||mwNoticeBusy||mwMailBusy||!!mwNoticePreview||!!mwMailPreview||!!prAction||!!prPreview||!!(section&&section.contains(document.activeElement))||previousBusy();};
 function mount(){
  const target=document.querySelector('#main-content .two-col');if(!target||document.getElementById('sec-payment-review'))return;
  target.insertAdjacentHTML('beforebegin',PR_HTML);
  target.insertAdjacentHTML('beforebegin',MW_NOTICE_HTML);
  target.insertAdjacentHTML('beforebegin',MW_ADMIN_UI);
  target.insertAdjacentHTML('beforebegin',MW_OVERVIEW_HTML);
  document.querySelector('#sec-payment-review .fp-body').insertAdjacentHTML('beforeend',MW_MAIL_HTML);
  if(typeof mwArrangeWorkspace==='function')mwArrangeWorkspace();
  prLoad(0);mwLoadOverview();
 }
 new MutationObserver(mount).observe(document.getElementById('main-content'),{childList:true,subtree:true});mount();
})();

let mwStatementPreview=null,mwStatementBusy=false;
async function mwStartStatement(){
 if(mwStatementBusy||!prProfile)return;mwStatementBusy=true;mwStatementPreview=null;const id=prProfile.memberId,el=document.getElementById('mw-statement');el.textContent='Preparing a read-only statement…';
 try{const input={task:'STATEMENT',memberIds:[id],requestId:crypto.randomUUID()},d=await fpCall('fp_admin_preview',input);if(!document.body.contains(el)||prProfile?.memberId!==id)return;mwStatementPreview={input,token:d.previewToken,statement:d.details.statement};const m=d.details.statement;el.innerHTML='<p>To: <strong>'+fpEscape(m.email)+'</strong> · '+fpEscape(m.generatedAt)+'</p><pre class="mw-email-preview">'+fpEscape(m.text)+'</pre><div class="fp-actions"><button class="hero-btn primary" onclick="mwSendStatement()">Confirm and email this member</button><button class="hero-btn secondary" onclick="mwCopyStatement()">Copy for WhatsApp</button><button class="hero-btn secondary" onclick="mwCloseStatement()">Close statement</button></div><p id="mw-statement-status" role="status">Preview only. No email sent.</p>';}
 catch(e){el.textContent=e.message;}finally{mwStatementBusy=false;}
}
function mwCloseStatement(){mwStatementPreview=null;const el=document.getElementById('mw-statement');if(el)el.textContent='';}
async function mwCopyStatement(){if(!mwStatementPreview)return;const el=document.getElementById('mw-statement-status');try{await navigator.clipboard.writeText(mwStatementPreview.statement.text);el.textContent='Copied. Paste into the verified member’s WhatsApp conversation. No message sent by the dashboard.';}catch(e){el.textContent='Clipboard unavailable. Select and copy the statement above.';}}
async function mwSendStatement(){
 if(mwStatementBusy||!mwStatementPreview)return;const p=mwStatementPreview;if(!confirm('Email this statement only to '+p.statement.email+'?'))return;mwStatementBusy=true;const el=document.getElementById('mw-statement-status');el.textContent='Sending the confirmed statement…';
 try{const d=await fpCall('fp_admin_apply',{...p.input,previewToken:p.token,confirmed:'YES'});el.textContent=d.alreadyRecorded?'This request was already completed; no repeat email was sent.':d.result?.email?.status==='SENT'?'Email accepted for delivery. Action timestamp recorded.':'Email outcome is uncertain. Check sent mail and the action audit before retrying.';mwStatementPreview=null;}
 catch(e){el.textContent=e.message+' Inspect the action audit before starting another request.';}finally{mwStatementBusy=false;}
}
